INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('how_we_work', '[{"step":"01","title":"Curated Collections","description":"We handpick the finest traditional and modern styles to match every woman''s unique taste.","href":"/shop"},{"step":"02","title":"Easy & Secure Shopping","description":"Browse, select, and pay with confidence through our user-friendly and secure platform.","href":"/shop"},{"step":"03","title":"Fast & Reliable Delivery","description":"Sit back and relax — your favorite fashion pieces arrive at your doorstep, quickly and safely.","href":"/contact-us"}]', '2026-09-13T10:13:59.058Z');
INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('testimonials', '[{"quote":"My gamcha saree from Womania turned every head at the pandal — the checks, the drape, everything felt so me.","name":"Womania Client","city":"West Bengal","rating":5},{"quote":"Wearing a custom Womania gown on the pageant stage felt like carrying our handloom story with pride.","name":"Pageant Contestant","city":"Designed by Dola","rating":5},{"quote":"Interning at the studio taught me how gamcha and khadi become real garments women love to wear.","name":"Design Intern","city":"Jalpaiguri Studio","rating":5},{"quote":"Finally found a brand that reflects my roots and modern taste. Totally in love with Womania!","name":"Priya S.","city":"Guwahati","rating":5}]', '2026-09-13T10:13:59.058Z');
INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('voices_gallery', '{"eyebrow":"Voices of Womania","title":"Real women. Real stories.","intro":"Clients in their favourite drapes, pageant contestants in custom gowns, and interns learning the craft at our Jalpaiguri studio — this is the community behind every stitch.","items":[{"id":"voice-01","image":"/testimonials/voices/01-client-studio-portrait.jpg","alt":"Womania client in a floral open jacket at a studio shoot","category":"client","caption":"Everyday elegance in Womania"},{"id":"voice-02","image":"/testimonials/voices/02-clients-gamcha-pair.jpg","alt":"Two clients wearing gamcha sarees and matching accessories","category":"client","caption":"Gamcha sisters at an event"},{"id":"voice-03","image":"/testimonials/voices/03-client-goddess-saree.jpg","alt":"Client in a hand-painted goddess motif saree","category":"client","caption":"Festive art saree"},{"id":"voice-04","image":"/testimonials/voices/04-client-gamcha-event.jpg","alt":"Client in red and white gamcha saree at a cultural programme","category":"client","caption":"Gamcha on stage"},{"id":"voice-05","image":"/testimonials/voices/05-client-gamcha-jewelry.jpg","alt":"Client in gamcha saree with shell jewellery","category":"client","caption":"Checks, shells & confidence"},{"id":"voice-06","image":"/testimonials/voices/06-studio-diwali-team.jpg","alt":"Team celebrating Diwali at the Womania studio","category":"studio","caption":"Studio diya celebration"},{"id":"voice-07","image":"/testimonials/voices/07-intern-heritage-experience.jpg","alt":"Intern experiencing traditional grain pounding at a heritage site","category":"intern","caption":"Learning beyond the studio"},{"id":"voice-08","image":"/testimonials/voices/08-studio-interns-team.jpg","alt":"Interns and team at the design studio","category":"intern","caption":"Our intern family"},{"id":"voice-09","image":"/testimonials/voices/09-intern-workshop.jpg","alt":"Intern at a rural workshop visit","category":"intern","caption":"Field visit with the team"},{"id":"voice-10","image":"/testimonials/voices/10-pageant-blue-gown.jpg","alt":"Pageant contestant in a custom blue Womania gown","category":"pageant","caption":"Custom pageant gown"},{"id":"voice-11","image":"/testimonials/voices/11-interns-studio-selfie.jpg","alt":"Interns smiling together inside the studio","category":"intern","caption":"Behind the sewing machine"},{"id":"voice-12","image":"/testimonials/voices/12-pageant-red-gown.jpg","alt":"Pageant contestant in a red Womania gown with brand badge","category":"pageant","caption":"Womania on the runway"},{"id":"voice-13","image":"/testimonials/voices/13-pageant-pink-yellow.jpg","alt":"Pageant contestant in pink and yellow custom outfit","category":"pageant","caption":"Bold colour on stage"},{"id":"voice-14","image":"/testimonials/voices/14-pageant-orange-green.jpg","alt":"Pageant contestant in orange and green handloom gown","category":"pageant","caption":"Handloom pageant look"},{"id":"voice-15","image":"/testimonials/voices/15-client-embroidered-jacket.jpg","alt":"Client in black gold-embroidered Womania jacket","category":"client","caption":"Embroidered statement piece"},{"id":"voice-16","image":"/testimonials/voices/16-studio-team-selfie.jpg","alt":"Dola and team selfie at Womania design studio","category":"studio","caption":"The design studio"},{"id":"voice-17","image":"/testimonials/voices/17-client-art-saree.jpg","alt":"Client in yellow art saree with fish motifs and matching jacket","category":"client","caption":"Hand-painted fish motifs"},{"id":"voice-18","image":"/testimonials/voices/18-client-gamcha-shrug.jpg","alt":"Client giving a thumbs up in a gamcha-pattern shrug","category":"client","caption":"Gamcha shrug, real life"}]}', '2026-09-13T10:13:59.058Z');
INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('about_us', '{"welcome":{"eyebrow":"About Us","title":"Welcome to Womania by Dola","intro":"At Womania, we''re all about blending tradition with modern style in a way that makes every woman feel elegant, confident, and unique. Founded by Dola Guha Neogi Roy, Womania started as a passion project and has grown into a brand that celebrates the beauty of Indian handloom fabrics with a fresh, contemporary twist."},"story":{"title":"The Story Behind Womania","paragraphs":["Womania was born from Dola''s love for Indian textiles and her vision to make them accessible to the modern woman. Her journey began with a fascination for Gamcha, Khadi, and Tribal fabrics from Assam and the Northeast — and a desire to make these traditional fabrics stand out in everyday fashion.","Starting with Gamcha dresses, sarees, and wrapped skirts, Womania quickly became known for beautifully crafted, sustainable pieces that connect tradition with modern style. Our mission is simple: to make every woman feel empowered and stylish, while supporting artisans and preserving the rich textile heritage of India."],"founderName":"Dola Guha Neogi Roy","founderBio":"The heart and soul behind Womania, Dola has always had a deep passion for Indian textiles. With a keen eye for design and a love for traditional fabrics, she has made it her mission to bring Gamcha, Khadi, and Tribal weaves into everyday fashion — pieces that feel as great as they look.","quote":"Crafted for the queen in you."},"philosophy":{"title":"Our Philosophy","paragraphs":["We believe fashion should be as comfortable as it is beautiful. Each garment is carefully crafted with fabrics that are timeless and incredibly wearable — from the simplicity of Gamcha to the elegance of Khadi and the vibrant patterns of Tribal fabrics from Assam and the Northeast.","Our designs reflect the unique style and spirit of every woman. Whether it''s a saree for a special occasion, a Gamcha dress for casual wear, or a wrapped skirt that adds tradition to a modern wardrobe, we have something for every moment."],"fabrics":[{"name":"Gamcha","note":"Patchwork colour & everyday ease"},{"name":"Khadi","note":"Breathable, elegant handloom"},{"name":"Tribal Weaves","note":"Northeast heritage & bold pattern"}]},"highlights":[{"title":"Craftsmanship","description":"Every piece is carefully made using authentic handloom fabrics sourced from talented artisans across India."},{"title":"Timeless Style","description":"Traditional techniques meet contemporary design — versatile pieces for any occasion."},{"title":"Sustainability","description":"Eco-friendly practices and ethical production, so fashion is beautiful and responsible."},{"title":"Customizable Fit","description":"Custom sizing on many garments — because everyone deserves to feel comfortable and confident."},{"title":"Celebrating Tradition","description":"We honour Indian artisans and craftsmanship, preserving the cultural heritage of our textiles."}],"promise":{"title":"Our Promise to You","paragraphs":["At Womania, we promise to continue creating fashion that''s not just about looking good, but feeling good too. Our clothing is for women who want to feel connected to tradition, but aren''t afraid to show off their modern style.","Thank you for choosing Womania by Dola. We''re excited to be part of your journey — one that celebrates heritage, creativity, and, of course, style."]}}', '2026-09-13T10:13:59.058Z');
INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('contact_us', '{"hero":{"eyebrow":"Contact Us","title":"Questions, orders & everything in between","intro":"Whether you''re choosing a gamcha shrug, tracking an order, or planning a custom fit — our studio in Jalpaiguri is only a message away."},"reach":[{"label":"WhatsApp","value":"Chat with us","href":"https://wa.me/919775301488","note":"Fastest for orders & sizing"},{"label":"Phone","value":"9775301488","href":"tel:9775301488","note":"Mon–Sat, 10 AM – 7 PM"},{"label":"Email","value":"womaniadesignstudio@gmail.com","href":"mailto:womaniadesignstudio@gmail.com","note":"Receipts & detailed queries"},{"label":"Studio","value":"Jalpaiguri, West Bengal","href":"https://maps.google.com/?q=Jalpaiguri+West+Bengal","note":"Newtown para, PO & District: Jalpaiguri"}],"faqEyebrow":"Information & Questions","faqTitle":"Frequently Asked Questions","formEyebrow":"Write to the Studio","formTitle":"Contact us for any questions","formNote":"Share your details and we''ll reply on WhatsApp or email — usually within one business day.","faqs":[{"id":"product-match","question":"Will I receive the same product that I see in the picture?","answer":["At Womania, we ensure that the product you see in the picture is exactly what you receive. All our product images are professionally photographed to reflect the actual design, colour, and details.","If you ever face any issue, our customer support is always here to help."]},{"id":"sales-receipt","question":"Where can I view my sales receipt?","answer":["You can view your sales receipt in the following ways:"],"list":["Email confirmation — a receipt is sent to your registered email after placing an order. Check your inbox or spam folder.","My Account → Orders — log in on womaniabydola.com, open Orders, and view or download your receipt.","Need help? Contact us with your order number and we''ll resend it right away."]},{"id":"returns","question":"How can I return an item?","intro":"Returning an item at Womania is simple and hassle-free.","steps":["Go to My Account → Orders, log in, and select the order you wish to return.","Click Request Return, choose the item and reason, then submit your request.","You''ll receive return instructions by email; our partner may arrange a pickup.","Once verified, your refund is processed within 5–7 business days."]},{"id":"restock","question":"Will you restock items indicated as \"out of stock?\"","answer":["Yes, we do restock popular items. If something is out of stock, click Notify Me on the product page to get an update when it''s available again."]},{"id":"shipping","question":"Where can I ship my order?","answer":["You can ship your order anywhere across India. Enter your complete shipping address at checkout and we''ll deliver it to your doorstep."]}]}', '2026-09-13T10:13:59.058Z');
INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('store_contact', '{"phone":"9775301488","phoneHref":"tel:9775301488","email":"womaniadesignstudio@gmail.com","emailHref":"mailto:womaniadesignstudio@gmail.com","address":"Newtown para, PO & District: Jalpaiguri","whatsappHref":"https://wa.me/919775301488","hours":"Mon–Sat · 10:00 AM – 7:00 PM IST"}', '2026-09-13T10:13:59.058Z');
