INSERT OR REPLACE INTO site_content (key, value, updated_at) VALUES ('policies', '{"shipping":"Orders ship within 3–5 business days across India.","returns":"Returns accepted within 7 days for unused items.","privacy":"We respect your privacy and never share customer data.","terms":"By ordering you agree to our store terms.","faq":[],"sizeGuide":"Most outfits are free size unless noted on the product page.","care":"Hand wash or gentle machine wash for handloom fabrics."}', '2026-09-13T10:13:59.058Z');

